inline bool encode_stamp(const StateStamp& stamp, Frame& out) noexcept {
  if (!valid_stamp(stamp)) {
    return false;
  }

  Frame candidate{};
  candidate.type = kStateStampType;
  candidate.size = kStateStampBytes;

  ByteWriter writer(candidate.payload.data(), candidate.payload.size());
  if (!writer.u64(stamp.tick) || !writer.u64(stamp.host_hash) ||
      !writer.u64(stamp.peer_hash)) {
    return false;
  }
  if (writer.position() != kStateStampBytes) {
    return false;
  }

  out = candidate;
  return true;
}

inline bool decode_stamp(const Frame& frame, StateStamp& out) noexcept {
  if (frame.type != kStateStampType) {
    return false;
  }
  if (frame.size != kStateStampBytes) {
    return false;
  }

  ByteReader reader(frame.payload.data(), frame.size);
  StateStamp candidate{};
  if (!reader.u64(candidate.tick) || !reader.u64(candidate.host_hash) ||
      !reader.u64(candidate.peer_hash)) {
    return false;
  }
  if (!reader.at_end()) {
    return false;
  }
  if (!valid_stamp(candidate)) {
    return false;
  }

  out = candidate;
  return true;
}

AuditPut put(Queue& queue, const StateStamp& stamp) noexcept {
    if (!valid_stamp(stamp)) {
      return AuditPut::invalid;
    }
    if (next_ > kMaxStateTick) {
      return AuditPut::exhausted;
    }
    if (stamp.tick < next_) {
      return AuditPut::stale;
    }

    const std::uint64_t offset = stamp.tick - next_;
    if (offset >= kHashWindow) {
      return AuditPut::too_far;
    }

    const std::size_t index = static_cast<std::size_t>(offset / kHashPeriod);
    Slot& slot = queue[index];
    if (slot.has_value()) {
      return same_stamp(*slot, stamp) ? AuditPut::duplicate : AuditPut::conflict;
    }
    slot = stamp;
    return AuditPut::stored;
  }

bool poll(Comparison& out) noexcept {
    if (!local_[0].has_value() || !remote_[0].has_value()) {
      return false;
    }

    Comparison candidate{};
    candidate.tick = next_;
    candidate.host_equal = local_[0]->host_hash == remote_[0]->host_hash;
    candidate.peer_equal = local_[0]->peer_hash == remote_[0]->peer_hash;

    for (std::size_t i = 0; i + 1 < kHashCapacity; ++i) {
      local_[i] = local_[i + 1];
      remote_[i] = remote_[i + 1];
    }
    local_[kHashCapacity - 1].reset();
    remote_[kHashCapacity - 1].reset();

    next_ += kHashPeriod;
    out = candidate;
    return true;
  }

bool publish(study_net::Connection& connection, const study_net::DelayedLockstep& game,
             study_net::HashAudit& audit) {
    using namespace study_net;
    const auto host = study_hash::state_hash(game.state().left());
    const auto peer = study_hash::state_hash(game.state().right());
    if (!host || !peer) return false;
    const StateStamp stamp{game.next_tick(), *host, *peer};
    if (audit.record_local(stamp) != AuditPut::stored) return false;
    Frame frame;
    if (!encode_stamp(stamp, frame)) return false;
    return connection.send_frame(frame, std::chrono::steady_clock::now() + std::chrono::seconds(2)).outcome == SendOutcome::complete;
}

bool compare_ready(study_net::HashAudit& audit) {
    study_net::Comparison comparison;
    while (audit.poll(comparison)) {
        std::printf("CHECK tick=%llu host=%s peer=%s\n",static_cast<unsigned long long>(comparison.tick),
            comparison.host_equal ? "match" : "mismatch",comparison.peer_equal ? "match" : "mismatch");
        if (!comparison.matched()) return false;
    }
    return true;
}
